  "Mkt3L10n.DataFormPanel.This_option_allows_control_how_filters_separated": "<p>このオプションを使用すると、フィルターの使用方法を制御できます。影響を受けるのはフィルターのみで、トリガーは個別に適用されます。</p><p>フィルター番号を \"and\" と \"or\" で区切って入力します。</p><ul><li>1 and 2 and 3</li><li>1 or 2 or 3</li></ul><p>\"and\" と \"or\" を混在させる場合は、意図を明確にするために括弧が必要です。たとえば、\"1 or 2 and 3\" は次のいずれかのように記述する必要があります。</p><ul><li>1 and (2 or 3)</li><li>(1 and 2) or 3</li></ul><p>より複雑なロジックでは、入れ子になった括弧が必要になる場合があります。</p><ul><li>(1 and 2) or (3 and 4)</li><li>1 and (2 or (3 and 4))</li></ul><br /><p><img src=\"/images/icons16/sign_warning.png\" class=\"mki16-p\" /> 挿入、削除、または並べ替えを行った後は、ルールを確認してください。</p>",
